/* File: libmath.c */
int add(int a, int b) {
  return a + b;
}

/* File: main.c */
#include <stdio.h>
extern int add(int, int); // Declare function from libmath.c
int main() {
  int sum = add(5, 3);
  printf("Sum: %d\n", sum);
  return 0;
}

/* Compile and Link (using GCC): */
gcc -c libmath.c -o libmath.o
gcc main.c libmath.o -o main
